// Everything a user typed (names, tool names) goes through escapeHtml before it reaches
// the HTML, so a tool called "<b>Drill</b> & Saw" shows up literally.
const escapeHtml = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// What the Error Trigger gives us: { execution: { id, url, error, lastNodeExecuted }, workflow: { id, name } }.
// A trigger that fails before an execution exists sends { trigger: { error } } instead.
const { execution = {}, workflow = {}, trigger } = $('Error Trigger').first().json;
const error = execution.error ?? trigger?.error ?? {};
const failure = {
  workflowName: workflow.name ?? 'Unknown workflow',
  nodeName: error.node?.name ?? execution.lastNodeExecuted,
  executionId: String(execution.id ?? `trigger-${workflow.id}-${Date.now()}`),
  message: String(error.message ?? 'Unknown error'),
  link: execution.url ?? '',
};


// The ops email: what failed, where, and a link to the execution in n8n.
const rows = [
  ['Workflow', failure.workflowName],
  ['Node', failure.nodeName ?? '—'],
  ['Execution', failure.executionId],
  ['Error', failure.message],
];
const html = [
  '<div style="font-family:system-ui,-apple-system,sans-serif;color:#18181b">',
  '<p>A LendLoop workflow failed.</p>',
  '<table cellpadding="4">',
  ...rows.map(([k, v]) => `<tr><th align="left">${k}</th><td>${escapeHtml(v)}</td></tr>`),
  '</table>',
  failure.link ? `<p><a href="${escapeHtml(failure.link)}">Open the execution in n8n</a></p>` : '',
  '</div>',
].join('\n');

return [{
  json: {
    to: 'ops@lendloop.local',
    subject: `[LendLoop] Workflow failed: ${failure.workflowName}`,
    html,
    text: rows.map(([k, v]) => `${k}: ${v}`).join('\n') + (failure.link ? `\n\n${failure.link}\n` : '\n'),
  },
}];

// --- sign: identical in every LendLoop workflow ---
// Same algorithm as signRequest in convex/lib/signature.ts:
//   X-LendLoop-Signature: t=<unix seconds>,v1=HMAC-SHA256(secret, `${t}.${METHOD}.${path}.${body}`)
// The HTTP Request node sends `rawBody` as a raw string, so the signed bytes are the sent bytes.
const crypto = require('crypto');
function sign(method, path, body) {
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto
    .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
    .update(`${t}.${method}.${path}.${body}`, 'utf8')
    .digest('hex');
  const base = $env.LENDLOOP_CONVEX_SITE_URL.replace(/\/$/, '');
  return { url: base + path, signature: `t=${t},v1=${v1}`, rawBody: body };
}
// --- end sign ---

// What the Error Trigger gives us: { execution: { id, url, error, lastNodeExecuted }, workflow: { id, name } }.
// A trigger that fails before an execution exists sends { trigger: { error } } instead.
const { execution = {}, workflow = {}, trigger } = $('Error Trigger').first().json;
const error = execution.error ?? trigger?.error ?? {};
const failure = {
  workflowName: workflow.name ?? 'Unknown workflow',
  nodeName: error.node?.name ?? execution.lastNodeExecuted,
  executionId: String(execution.id ?? `trigger-${workflow.id}-${Date.now()}`),
  message: String(error.message ?? 'Unknown error'),
  link: execution.url ?? '',
};


// Record the failure in LendLoop so admins see it in the app. The app shows this text, so
// email addresses (SMTP errors can contain them) are masked; Convex de-duplicates by executionId.
const message = failure.message.replace(/[^\s<>@]+@[^\s<>@]+/g, '[email]').slice(0, 500);
const body = JSON.stringify({
  workflowName: failure.workflowName,
  nodeName: failure.nodeName, // dropped by JSON.stringify when unknown
  executionId: failure.executionId,
  message,
});
return [{ json: sign('POST', '/automation/errors', body) }];
